// Typed access to the M1 sample avatars (generated by scripts/make-fixtures.mjs). M2 replaces
// these with the live engine; components only depend on this shape.
import data from "@/fixtures/fixtures.json";
import type { Section, StyleId } from "@/content/styles";

export type StyleFixture = {
  seed: string;
  frameNo: number;
  hero: string;
  /** The current value of every part (and sub-colour), keyed by config field. */
  selected: Record<string, string>;
  /** Option tile images per tile section, in option order. */
  tiles: Record<string, string[]>;
  /** Earlier rolls, oldest first; the last entry is the current avatar. */
  history: string[];
  /** Twelve random avatars that keep the locked parts (Grid view). */
  sheet: string[];
};

export const fixtures = data as Record<StyleId, StyleFixture>;

export const optionLabel = (section: Section, index: number) => {
  if (section.kind !== "tiles") return "";
  const id = section.options[index];
  return section.labels?.[index] ?? id.charAt(0).toUpperCase() + id.slice(1);
};
